                                  'from lru import OrdemLRU\n'
                                  '\n'
                                  '\n'
                                  'class CacheLRU:\n'
                                  '    """Cache de capacidade fixa com expulsão LRU e expiração '
                                  'por TTL.\n'
                                  '\n'
                                  '    O TTL é medido em ticks do relógio lógico injetado; nada '
                                  'aqui\n'
                                  '    consulta o relógio de parede.\n'
                                  '    """\n'
                                  '\n'
                                  '    def __init__(self, capacidade, ttl, relogio):\n'
                                  '        if capacidade < 1:\n'
                                  '            raise ValueError(f"capacidade deve ser >= 1: '
                                  '{capacidade}")\n'
                                  '        self.capacidade = capacidade\n'
                                  '        self.ttl = ttl\n'
                                  '        self._relogio = relogio\n'
                                  '        self._dados = {}\n'
                                  '        self._ordem = OrdemLRU()\n'
                                  '\n'
