                               '\n'
                               '    def __init__(self, valor, criada_em, ttl):\n'
                               '        if ttl < 1:\n'
                               '            raise ValueError(f"ttl deve ser >= 1: {ttl}")\n'
                               '        self.valor = valor\n'
                               '        self.criada_em = criada_em\n'
                               '        self.expira_em = criada_em + ttl\n'
