                           'from ordenacao import ordena\n'
                           'from tabela import parse_tabela\n'
                           '\n'
                           '\n'
                           'def consulta(texto, coluna=None, op=None, alvo=None,\n'
                           '             ordenar_por=None, decrescente=False):\n'
                           '    """Parse do texto, filtro opcional e ordenação opcional, nessa '
                           'ordem."""\n'
                           '    _, linhas = parse_tabela(texto)\n'
                           '    if coluna is not None:\n'
                           '        linhas = filtra(linhas, coluna, op, alvo)\n'
                           '    if ordenar_por is not None:\n'
                           '        linhas = ordena(linhas, ordenar_por, decrescente)\n'
