                              '        linhas.append(dict(zip(colunas, valores)))\n'
                              '    return colunas, linhas\n'
                              '\n'
                              '\n'
                              'def como_numero(valor):\n'
                              '    """Converte para int quando possível; senão devolve a própria '
                              'string."""\n'
                              '    try:\n'
                              '        return int(valor)\n'
                              '    except ValueError:\n'
                              '        return valor\n'
                              '\n'
                              '\n'
                              'def largura_colunas(colunas, linhas):\n'
                              '    """Largura máxima (em caracteres) de cada coluna, para '
                              'exibição."""\n'
                              '    larguras = {c: len(c) for c in colunas}\n'
