                                    'import heapq\n'
                                    'from collections import deque\n'
                                    '\n'
                                    '\n'
                                    'def caminho_bfs(grafo, origem: str, destino: str):\n'
                                    '    """Caminho com menor numero de arestas, ou None se '
                                    'inalcancavel."""\n'
                                    '    if origem == destino:\n'
                                    '        return [origem]\n'
                                    '    anterior = {origem: None}\n'
                                    '    fila = deque([origem])\n'
                                    '    while fila:\n'
                                    '        atual = fila.popleft()\n'
                                    '        for viz in grafo.vizinhos(atual):\n'
                                    '            if viz not in anterior:\n'
                                    '                anterior[viz] = atual\n'
                                    '                if viz == destino:\n'
                                    '                    return _reconstroi(anterior, destino)\n'
                                    '                fila.append(viz)\n'
                                    '    return None\n'
                                    '\n'
                                    '\n'
                                    'def _reconstroi(anterior: dict, destino: str) -> list[str]:\n'
                                    '    """Reconstroi o caminho seguindo os antecessores ate a '
                                    'origem."""\n'
                                    '    caminho = [destino]\n'
                                    '    no = anterior[destino]\n'
                                    '    while no is not None:\n'
                                    '        caminho.append(no)\n'
                                    '        no = anterior[no]\n'
                                    '    caminho.reverse()\n'
                                    '    return caminho\n'
                                    '\n'
                                    '\n'
                                    'def distancia_dijkstra(grafo, origem: str, destino: str):\n'
                                    '    """Custo minimo (soma dos pesos) de origem a destino, ou '
                                    'None."""\n'
                                    '    melhores = {origem: 0}\n'
                                    '    heap = [(0, origem)]\n'
                                    '    while heap:\n'
                                    '        custo, atual = heapq.heappop(heap)\n'
                                    '        if custo > melhores.get(atual, custo):\n'
                                    '            continue\n'
                                    '        if atual == destino:\n'
                                    '            return custo\n'
                                    '        for viz in grafo.vizinhos(atual):\n'
