                                '\n'
                                'CATALOGO = {\n'
                                '    "parafuso": {"nome": "Parafuso M4", "minimo": 10},\n'
                                '    "porca": {"nome": "Porca M4", "minimo": 5},\n'
                                '    "arruela": {"nome": "Arruela lisa", "minimo": 20},\n'
                                '}\n'
                                '\n'
                                '\n'
                                'def existe(codigo):\n'
                                '    """True se o código pertence ao catálogo."""\n'
                                '    return codigo in CATALOGO\n'
                                '\n'
                                '\n'
                                'def valida(codigo):\n'
                                '    """ValueError se o código não pertence ao catálogo."""\n'
                                '    if not existe(codigo):\n'
                                '        raise ValueError(f"produto desconhecido: {codigo!r}")\n'
                                '\n'
                                '\n'
                                'def minimo(codigo):\n'
                                '    """Saldo mínimo de reposição do produto."""\n'
