                            '        return (achado.start(), achado.end(), "var", '
                            'limpa(achado.group(1)))\n'
                            '    bruto = limpa(achado.group(2))\n'
                            '    palavra, _, resto = bruto.partition(" ")\n'
                            '    return (achado.start(), achado.end(), palavra, limpa(resto))\n'
