                                '\n'
                                '\n'
                                'def total_tokens(freq: dict[str, int]) -> int:\n'
                                '    """Soma de todas as frequencias."""\n'
                                '    return sum(freq.values())\n'
                                '\n'
                                '\n'
                                'def vocabulario(freq: dict[str, int]) -> list[str]:\n'
                                '    """Palavras distintas em ordem alfabetica."""\n'
